'use client';

import { useCallback, useMemo, useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import {
  pressedQuietOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { ChevronLeftIcon, ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import {
  Pagination,
  PaginationContent,
  PaginationItem,
} from '@/registry/ndeko/ui/pagination';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Tabs, TabsList, TabsPanel, TabsTab } from '@/registry/ndeko/ui/tabs';

import { AccountsTable } from './accounts-table';
import type { FilterKind } from './ask';
import { AskBar } from './ask-bar';
import { BulkBar } from './bulk-bar';
import { csvRowsOf, downloadCsv } from './csv';
import { TODAY_LABEL, type OwnerId } from './data';
import {
  accountsWordOf,
  INITIAL,
  LOOP_AFTER_MS,
  matchingOf,
  PAGE_SIZE,
  pageCountOf,
  pageRowsOf,
  reducer,
  RESTING,
  resultOf,
  SCRIPT,
  viewCountOf,
  VIEWS,
  type AccountsAction,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const FILE_NAME = 'accounts.csv';

const EXPORTED_FOR_MS = 1600;

/** 1 to 8 of 24: the rows on screen out of the rows the filters keep. */
function rangeLineOf(page: number, shown: number, total: number) {
  if (total === 0) {
    return 'No account';
  }
  const first = page * PAGE_SIZE + 1;
  const last = first + shown - 1;
  return `${first} to ${last} of ${total}`;
}

export default function AiData01() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const [isExported, setIsExported] = useState(false);
  const { filters, view, sort, page } = state;
  const matching = useMemo(() => matchingOf(filters), [filters]);
  const result = useMemo(
    () => resultOf(filters, view, sort),
    [filters, view, sort]
  );
  const rows = useMemo(() => pageRowsOf(result, page), [result, page]);
  const total = result.length;
  const pageCount = pageCountOf(total);
  const pageNumber = page + 1;
  const isFirstPage = page === 0;
  const isLastPage = pageNumber === pageCount;
  const rangeLine = rangeLineOf(page, rows.length, total);
  const hasChanged = state.revision > 0;
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  const focusLater = useCallback(
    (selector: string) => {
      requestAnimationFrame(() => {
        const target = ref.current?.querySelector<HTMLElement>(selector);
        target?.focus();
      });
    },
    [ref]
  );

  /** The button that removes the filters leaves with the empty state, so the focus goes back to the question box. */
  const actOnTable = useCallback(
    (action: AccountsAction) => {
      act(action);
      if (action.type === 'filtersCleared') {
        focusLater('[data-ask-field]');
      }
    },
    [act, focusLater]
  );

  /** A chip that is removed takes its button with it: the focus goes to the chip that takes its place, or to the question box. */
  function removeFilter(kind: FilterKind) {
    const kinds = filters.map((filter) => filter.kind);
    const index = kinds.indexOf(kind);
    const neighbour = kinds[index + 1] ?? kinds[index - 1];
    act({ type: 'filterRemoved', kind });
    if (neighbour) {
      focusLater(`[data-filter-remove="${neighbour}"]`);
      return;
    }
    focusLater('[data-ask-field]');
  }

  function clearFilters() {
    act({ type: 'filtersCleared' });
    focusLater('[data-ask-field]');
  }

  function pickView(value: unknown) {
    const picked = VIEWS.find((candidate) => candidate.id === value);
    if (picked) {
      act({ type: 'viewPicked', view: picked.id });
    }
  }

  function showOwners() {
    act({ type: 'bulkModeSet', mode: 'owners' });
    focusLater('[data-bulk-owner]');
  }

  function hideOwners() {
    act({ type: 'bulkModeSet', mode: 'actions' });
    focusLater('[data-bulk-assign]');
  }

  /** The bar leaves once its accounts have their owner, so the focus goes back to the table. */
  function assign(owner: OwnerId) {
    act({ type: 'ownerAssigned', owner });
    focusLater('[data-select-page]');
  }

  function clearSelection() {
    act({ type: 'selectionCleared' });
    focusLater('[data-select-page]');
  }

  function exportSelected() {
    const chosen = result.filter((account) =>
      state.selected.includes(account.id)
    );
    downloadCsv(FILE_NAME, csvRowsOf(chosen, state.owners));
    act({ type: 'exported' });
    setIsExported(true);
    schedule(() => setIsExported(false), EXPORTED_FOR_MS);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-6xl flex-col gap-4 p-4 @3xl:gap-5 @3xl:p-8'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
              <h1 className='text-lg font-semibold text-balance'>Accounts</h1>
              <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-1 text-xs'>
                <span className='flex items-baseline gap-1'>
                  <MotionNumber value={total} />
                  {accountsWordOf(total)}
                </span>
                <span aria-hidden='true'>·</span>
                As of {TODAY_LABEL}
                <Badge variant='secondary'>Illustrative</Badge>
              </p>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay'
            />
          </header>

          <AskBar
            question={state.question}
            hasAskFailed={state.hasAskFailed}
            filters={filters}
            pressed={pressed}
            onType={(text) => act({ type: 'questionTyped', text })}
            onAsk={() => act({ type: 'asked' })}
            onRemove={removeFilter}
            onClear={clearFilters}
          />

          <Tabs value={view} onValueChange={pickView} className='gap-4'>
            <TabsList aria-label='Saved views'>
              {VIEWS.map((candidate) => (
                <TabsTab
                  key={candidate.id}
                  value={candidate.id}
                  className={cn(
                    'transition-[color,background-color,scale]',
                    pressedQuietOf(pressed === `view-${candidate.id}`)
                  )}
                >
                  {candidate.label}
                  <span className='text-muted-foreground text-xs'>
                    <MotionNumber value={viewCountOf(matching, candidate.id)} />
                  </span>
                </TabsTab>
              ))}
            </TabsList>
            <TabsPanel value={view} className='flex flex-col gap-3'>
              <div className='bg-card hairline-ring ring-border @container min-h-[26.5rem] overflow-hidden rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
                <AccountsTable
                  rows={rows}
                  owners={state.owners}
                  sort={sort}
                  selected={state.selected}
                  openSummaries={state.openSummaries}
                  writtenSummaries={state.writtenSummaries}
                  streamingSummary={state.streamingSummary}
                  hasChanged={hasChanged}
                  pressed={pressed}
                  onAction={actOnTable}
                />
              </div>
              <Pagination className='items-center justify-between gap-3'>
                <p className='text-muted-foreground text-xs tabular-nums'>
                  {rangeLine}
                </p>
                <PaginationContent>
                  <PaginationItem>
                    <Button
                      type='button'
                      variant='outline'
                      size='icon-sm'
                      aria-label='Go to the previous page'
                      disabled={isFirstPage}
                      focusableWhenDisabled
                      onClick={() =>
                        act({ type: 'pageTurned', page: page - 1 })
                      }
                    >
                      <ChevronLeftIcon />
                    </Button>
                  </PaginationItem>
                  <PaginationItem>
                    <p className='text-muted-foreground px-1 text-xs tabular-nums'>
                      Page {pageNumber} of {pageCount}
                    </p>
                  </PaginationItem>
                  <PaginationItem>
                    <Button
                      type='button'
                      variant='outline'
                      size='icon-sm'
                      aria-label='Go to the next page'
                      disabled={isLastPage}
                      focusableWhenDisabled
                      onClick={() =>
                        act({ type: 'pageTurned', page: page + 1 })
                      }
                    >
                      <ChevronRightIcon />
                    </Button>
                  </PaginationItem>
                </PaginationContent>
              </Pagination>
            </TabsPanel>
          </Tabs>

          <BulkBar
            count={state.selected.length}
            mode={state.bulkMode}
            isExported={isExported}
            pressed={pressed}
            onShowOwners={showOwners}
            onHideOwners={hideOwners}
            onAssign={assign}
            onExport={exportSelected}
            onClear={clearSelection}
          />
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion, type MotionProps } from 'motion/react';
import { useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import { XIcon } from '@/registry/ndeko/lib/icons';
import { EASE_OUT_STRONG, springOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import { Input } from '@/registry/ndeko/ui/input';

import {
  ASK_EXAMPLE,
  ASK_FAILED_LINE,
  filterLabelOf,
  type Filter,
  type FilterKind,
} from './ask';

const CHIP =
  'chip-3d inline-flex h-7 max-w-full items-center gap-0.5 rounded-md ps-2 pe-0.5 text-xs font-medium whitespace-nowrap [--chip:var(--primary)]';

const CHIP_REMOVE =
  'focus-visible:ring-ring/25 hover:bg-foreground/[0.08] flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-sm opacity-70 transition-[opacity,background-color,scale] duration-150 outline-none hover:opacity-100 focus-visible:opacity-100 focus-visible:ring-[3px]';

/** The chips of one question land one after the other. */
const LANDING_STAGGER = 0.06;

const LEAVE = { duration: 0.12, ease: EASE_OUT_STRONG };

type ChipPresence = Pick<MotionProps, 'initial' | 'animate' | 'exit'>;

const CHIP_FADE: ChipPresence = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: LEAVE },
};

/** A chip settles from a slightly larger size. Reduced motion keeps the fade only. */
function chipPresenceOf(
  shouldReduceMotion: boolean,
  order: number
): ChipPresence {
  if (shouldReduceMotion) {
    return CHIP_FADE;
  }
  const delay = order * LANDING_STAGGER;
  const land = { duration: 0.3, ease: EASE_OUT_STRONG, delay };
  return {
    initial: { opacity: 0, scale: 1.04 },
    animate: { opacity: 1, scale: 1, transition: land },
    exit: { opacity: 0, scale: 0.96, transition: LEAVE },
  };
}

function describedByOf(hasAskFailed: boolean, hintId: string) {
  if (hasAskFailed) {
    return hintId;
  }
  return undefined;
}

type AskBarProps = {
  question: string;
  hasAskFailed: boolean;
  filters: Filter[];
  pressed: string | null;
  onType: (text: string) => void;
  onAsk: () => void;
  onRemove: (kind: FilterKind) => void;
  onClear: () => void;
};

export function AskBar({
  question,
  hasAskFailed,
  filters,
  pressed,
  onType,
  onAsk,
  onRemove,
  onClear,
}: AskBarProps) {
  const fieldId = useId();
  const hintId = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const travel = springOf(shouldReduceMotion);
  const kinds = filters.map((filter) => filter.kind);
  const placement = kinds.join(' ');
  const hasFilters = filters.length > 0;

  function ask(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onAsk();
  }

  return (
    <section aria-label='Ask the table' className='flex flex-col gap-2'>
      <form onSubmit={ask} className='flex flex-col gap-1.5'>
        <div className='flex items-center gap-2'>
          <label
            htmlFor={fieldId}
            className='text-muted-foreground shrink-0 text-[13px]'
          >
            Show me
          </label>
          <Input
            id={fieldId}
            data-ask-field
            autoComplete='off'
            placeholder={ASK_EXAMPLE}
            value={question}
            aria-invalid={hasAskFailed}
            aria-describedby={describedByOf(hasAskFailed, hintId)}
            onChange={(event) => onType(event.target.value)}
          />
          <Button
            type='submit'
            className={cn('shrink-0', pressedSolidOf(pressed === 'ask'))}
          >
            Ask
          </Button>
        </div>
        <Fold open={hasAskFailed}>
          <p id={hintId} className='text-destructive-ink text-xs'>
            {ASK_FAILED_LINE}
          </p>
        </Fold>
      </form>
      <div className='flex min-h-7 flex-wrap items-center gap-x-2 gap-y-1.5'>
        {!hasFilters && (
          <p className='text-muted-foreground text-xs'>
            Name a plan, a region, seats over or under a number, or what renews
            this quarter
          </p>
        )}
        <ul
          aria-label='Filters'
          className='relative flex flex-wrap items-center gap-1.5'
        >
          <AnimatePresence mode='popLayout' initial={false}>
            {filters.map((filter, index) => {
              const label = filterLabelOf(filter);
              const isPressed = pressed === `chip-${filter.kind}`;
              return (
                <motion.li
                  key={filter.kind}
                  layout='position'
                  layoutDependency={placement}
                  {...chipPresenceOf(shouldReduceMotion, index)}
                  transition={{ layout: travel }}
                  className='max-w-full'
                >
                  <span className={CHIP}>
                    <span className='min-w-0 truncate'>{label}</span>
                    <button
                      type='button'
                      data-filter-remove={filter.kind}
                      aria-label={`Remove the filter ${label}`}
                      onClick={() => onRemove(filter.kind)}
                      className={cn(CHIP_REMOVE, pressedQuietOf(isPressed))}
                    >
                      <XIcon className='size-3.5' />
                    </button>
                  </span>
                </motion.li>
              );
            })}
          </AnimatePresence>
        </ul>
        {hasFilters && (
          <Button
            type='button'
            variant='ghost'
            size='sm'
            onClick={onClear}
            className='text-muted-foreground'
          >
            Clear filters
          </Button>
        )}
      </div>
    </section>
  );
}

'use client';

import { memo, useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { ArrowUpIcon, TextQuoteIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold, Swap } from '@/registry/ndeko/ui/chat-motion';
import { Checkbox } from '@/registry/ndeko/ui/checkbox';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';
import { StreamedInk } from '@/registry/ndeko/ui/streamed-text';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/registry/ndeko/ui/table';

import {
  HEALTH_LABEL,
  ownerOf,
  PLAN_LABEL,
  REGION_LABEL,
  renewalLabelOf,
  summaryOf,
  type Account,
  type Health,
  type OwnerId,
} from './data';
import {
  ownerIdOf,
  SORT_LABEL,
  type AccountsAction,
  type Owners,
  type Sort,
  type SortColumn,
  type SortDirection,
} from './session';

const COLUMN_COUNT = 9;

/** How long one word of a summary takes to follow the one before it. */
const WORD_MS = 45;

const HEALTH_VARIANT: Record<Health, 'success' | 'warning' | 'destructive'> = {
  healthy: 'success',
  watch: 'warning',
  risk: 'destructive',
};

const SORT_BUTTON =
  'group/sort focus-visible:ring-ring/25 hover:bg-foreground/[0.05] hover:text-foreground -mx-1.5 inline-flex h-7 cursor-pointer items-center gap-1 rounded-md px-1.5 transition-[background-color,color,scale] duration-150 outline-none focus-visible:ring-[3px]';

/**
 * The table scrolls sideways inside its frame on a narrow page. What belongs to a whole row (its
 * summary, the empty state) stays as wide as the frame and holds to its left edge, so it is read
 * without scrolling.
 */
const FRAME_WIDE = 'sticky left-0 w-[100cqw]';

function ariaSortOf(isSorted: boolean, direction: SortDirection) {
  if (!isSorted) {
    return 'none';
  }
  if (direction === 'asc') {
    return 'ascending';
  }
  return 'descending';
}

function arrowClassOf(isSorted: boolean, direction: SortDirection) {
  if (!isSorted) {
    return 'opacity-0 group-hover/sort:opacity-40 group-focus-visible/sort:opacity-40';
  }
  if (direction === 'asc') {
    return 'opacity-100';
  }
  return 'rotate-180 opacity-100';
}

type SortHeadProps = {
  column: SortColumn;
  sort: Sort;
  pressed: string | null;
  /** A column of figures: the label ends where the figures end, the arrow sits before it. */
  isFigure?: boolean;
  onAction: (action: AccountsAction) => void;
};

function SortHead({
  column,
  sort,
  pressed,
  isFigure = false,
  onAction,
}: SortHeadProps) {
  const isSorted = sort.column === column;
  const isPressed = pressed === `sort-${column}`;

  return (
    <TableHead
      aria-sort={ariaSortOf(isSorted, sort.direction)}
      className={cn(isFigure && 'text-end')}
    >
      <button
        type='button'
        onClick={() => onAction({ type: 'sorted', column })}
        className={cn(
          SORT_BUTTON,
          isFigure && 'flex-row-reverse',
          pressedQuietOf(isPressed)
        )}
      >
        {SORT_LABEL[column]}
        <ArrowUpIcon
          aria-hidden='true'
          className={cn(
            'size-3.5 transition-[opacity,rotate] duration-200 ease-(--ease-out-strong)',
            arrowClassOf(isSorted, sort.direction)
          )}
        />
      </button>
    </TableHead>
  );
}

function selectedStateOf(isSelected: boolean) {
  if (isSelected) {
    return 'selected';
  }
  return undefined;
}

/** A row that arrives after the first change of the list fades in. Nothing fades when the page loads. */
function arrivalOf(hasChanged: boolean) {
  if (hasChanged) {
    return 'transition-[background-color,opacity] duration-[150ms,300ms] starting:opacity-0';
  }
  return undefined;
}

/** A gradient alone names nobody: the first name sits beside it, the full name once the table has room. */
function OwnerCell({ ownerId }: { ownerId: OwnerId }) {
  const owner = ownerOf(ownerId);

  return (
    <Swap swapKey={owner.id}>
      <span className='flex items-center gap-2 whitespace-nowrap'>
        <Avatar seed={owner.name} className='size-5' />
        <span className='@5xl:hidden'>{owner.firstName}</span>
        <span className='hidden @5xl:inline'>{owner.name}</span>
      </span>
    </Swap>
  );
}

type AccountRowProps = {
  account: Account;
  ownerId: OwnerId;
  isSelected: boolean;
  isSummaryOpen: boolean;
  isSummaryWritten: boolean;
  isSummaryStreaming: boolean;
  isLast: boolean;
  hasChanged: boolean;
  pressed: string | null;
  onAction: (action: AccountsAction) => void;
};

function AccountRow({
  account,
  ownerId,
  isSelected,
  isSummaryOpen,
  isSummaryWritten,
  isSummaryStreaming,
  isLast,
  hasChanged,
  pressed,
  onAction,
}: AccountRowProps) {
  const summaryId = useId();
  const isSelectPressed = pressed === `select-${account.id}`;
  const isSummarizePressed = pressed === `summarize-${account.id}`;
  const endsTheList = isLast && !isSummaryOpen;
  const hasLineUnderSummary = isSummaryOpen && !isLast;

  return (
    <>
      <TableRow
        data-state={selectedStateOf(isSelected)}
        className={cn('h-12', arrivalOf(hasChanged), endsTheList && 'border-0')}
      >
        <TableCell className='py-0'>
          <Checkbox
            checked={isSelected}
            aria-label={`Select ${account.name}`}
            onCheckedChange={() =>
              onAction({ type: 'rowToggled', id: account.id })
            }
            className={cn(
              'transition-[background-color,box-shadow,scale]',
              pressedQuietOf(isSelectPressed)
            )}
          />
        </TableCell>
        <TableCell className='w-full max-w-0 py-0'>
          <span className='flex min-w-0 items-center gap-2.5'>
            <CompanyMark seed={account.name} />
            <span className='truncate font-medium'>{account.name}</span>
          </span>
        </TableCell>
        <TableCell className='py-0 whitespace-nowrap'>
          {PLAN_LABEL[account.plan]}
        </TableCell>
        <TableCell className='text-muted-foreground hidden py-0 whitespace-nowrap @4xl:table-cell'>
          {REGION_LABEL[account.region]}
        </TableCell>
        <TableCell className='py-0 text-end tabular-nums'>
          {account.seats}
        </TableCell>
        <TableCell className='py-0 whitespace-nowrap tabular-nums'>
          {renewalLabelOf(account.renewal)}
        </TableCell>
        <TableCell className='py-0'>
          <Badge variant={HEALTH_VARIANT[account.health]}>
            {HEALTH_LABEL[account.health]}
          </Badge>
        </TableCell>
        <TableCell className='py-0'>
          <OwnerCell ownerId={ownerId} />
        </TableCell>
        <TableCell className='py-0 ps-0'>
          <Button
            type='button'
            variant='ghost'
            size='sm'
            aria-label={`Summarize ${account.name}`}
            aria-expanded={isSummaryOpen}
            aria-controls={summaryId}
            onClick={() => onAction({ type: 'summaryToggled', id: account.id })}
            className={cn(
              'text-muted-foreground',
              pressedQuietOf(isSummarizePressed)
            )}
          >
            <TextQuoteIcon />
            <span className='hidden @3xl:inline'>Summarize</span>
          </Button>
        </TableCell>
      </TableRow>
      <tr className={cn(hasLineUnderSummary && 'hairline-b border-border')}>
        <td colSpan={COLUMN_COUNT} className='p-0'>
          <div className={cn(FRAME_WIDE, 'px-1')}>
            <Fold open={isSummaryOpen} id={summaryId}>
              {isSummaryWritten && (
                <div className='bg-foreground/[0.03] my-1 flex flex-col gap-1.5 rounded-md px-3 py-2.5 @3xl:ps-[3.25rem]'>
                  <p className='max-w-prose text-[13px] leading-relaxed'>
                    <StreamedInk
                      text={summaryOf(account)}
                      isStreaming={isSummaryStreaming}
                      wordMs={WORD_MS}
                    />
                  </p>
                  <p className='text-muted-foreground text-xs'>
                    Written from this row
                  </p>
                </div>
              )}
            </Fold>
          </div>
        </td>
      </tr>
    </>
  );
}

type SelectPageBoxProps = {
  rowIds: string[];
  selected: string[];
  onAction: (action: AccountsAction) => void;
};

function SelectPageBox({ rowIds, selected, onAction }: SelectPageBoxProps) {
  const selectedOnPage = rowIds.filter((id) => selected.includes(id));
  const hasRows = rowIds.length > 0;
  const isPageSelected = hasRows && selectedOnPage.length === rowIds.length;
  const isPartlySelected = selectedOnPage.length > 0 && !isPageSelected;

  return (
    <Checkbox
      data-select-page
      checked={isPageSelected}
      indeterminate={isPartlySelected}
      disabled={!hasRows}
      aria-label='Select the accounts of this page'
      onCheckedChange={() => onAction({ type: 'pageToggled' })}
    />
  );
}

/** Under reduced motion a summary is there at once. */
function streamingIdOf(
  streamingSummary: string | null,
  shouldReduceMotion: boolean
) {
  if (shouldReduceMotion) {
    return null;
  }
  return streamingSummary;
}

export type AccountsTableProps = {
  rows: Account[];
  owners: Owners;
  sort: Sort;
  selected: string[];
  openSummaries: string[];
  writtenSummaries: string[];
  streamingSummary: string | null;
  hasChanged: boolean;
  pressed: string | null;
  onAction: (action: AccountsAction) => void;
};

/** Memoised: a key typed in the question box above does not draw the rows again. */
export const AccountsTable = memo(function AccountsTable({
  rows,
  owners,
  sort,
  selected,
  openSummaries,
  writtenSummaries,
  streamingSummary,
  hasChanged,
  pressed,
  onAction,
}: AccountsTableProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const streamingId = streamingIdOf(streamingSummary, shouldReduceMotion);
  const rowIds = rows.map((account) => account.id);
  const lastIndex = rows.length - 1;
  const isEmpty = rows.length === 0;
  const sortHead = { sort, pressed, onAction };

  return (
    <Table className='min-w-[44rem]'>
      <caption className='sr-only'>Customer accounts</caption>
      <TableHeader>
        <TableRow className='hover:bg-transparent'>
          <TableHead>
            <SelectPageBox
              rowIds={rowIds}
              selected={selected}
              onAction={onAction}
            />
          </TableHead>
          <SortHead column='name' {...sortHead} />
          <SortHead column='plan' {...sortHead} />
          <TableHead className='hidden @4xl:table-cell'>Region</TableHead>
          <SortHead column='seats' isFigure {...sortHead} />
          <SortHead column='renewal' {...sortHead} />
          <TableHead>Health</TableHead>
          <TableHead>Owner</TableHead>
          <TableHead className='ps-0'>
            <span className='sr-only'>Summary</span>
          </TableHead>
        </TableRow>
      </TableHeader>
      <TableBody>
        {rows.map((account, index) => (
          <AccountRow
            key={account.id}
            account={account}
            ownerId={ownerIdOf(owners, account)}
            isSelected={selected.includes(account.id)}
            isSummaryOpen={openSummaries.includes(account.id)}
            isSummaryWritten={writtenSummaries.includes(account.id)}
            isSummaryStreaming={streamingId === account.id}
            isLast={index === lastIndex}
            hasChanged={hasChanged}
            pressed={pressed}
            onAction={onAction}
          />
        ))}
        {isEmpty && (
          <TableRow className='hover:bg-transparent'>
            <TableCell colSpan={COLUMN_COUNT} className='p-0'>
              <div
                className={cn(
                  FRAME_WIDE,
                  'flex flex-col items-start gap-3 p-4'
                )}
              >
                <p className='text-muted-foreground text-[13px]'>
                  No account matches these filters
                </p>
                <Button
                  type='button'
                  variant='outline'
                  size='sm'
                  onClick={() => onAction({ type: 'filtersCleared' })}
                >
                  Remove the filters
                </Button>
              </div>
            </TableCell>
          </TableRow>
        )}
      </TableBody>
    </Table>
  );
});

