/** What the bar offers arrives with a fade, since the bar changes width around it. */
const CHOICES =
  'flex items-center gap-1 transition-opacity duration-200 starting:opacity-0';

function exportWordOf(isExported: boolean) {
  if (isExported) {
    return 'Exported';
  }
  return 'Export';
}

/** On a narrow bar the names of the owners need the room the count takes while one is picked. */
function countVisibilityOf(isPickingOwner: boolean) {
  if (isPickingOwner) {
    return 'hidden @lg:flex';
  }
  return 'flex';
}

type BulkBarProps = {
  count: number;
  mode: BulkMode;
  isExported: boolean;
  pressed: string | null;
  onShowOwners: () => void;
  onHideOwners: () => void;
  onAssign: (owner: OwnerId) => void;
  onExport: () => void;
  onClear: () => void;
};

/**
 * The bar keeps its place at the foot of the block whether it shows or not, so selecting a row
 * moves nothing. The owners are picked in the bar itself: no layer opens over the table.
 */
export function BulkBar({
  count,
  mode,
  isExported,
  pressed,
  onShowOwners,
  onHideOwners,
  onAssign,
  onExport,
  onClear,
}: BulkBarProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = risePresenceOf(shouldReduceMotion);
  const hasSelection = count > 0;
  const isPickingOwner = mode === 'owners';
  const exportWord = exportWordOf(isExported);

  function leaveOwnersOnEscape(event: React.KeyboardEvent<HTMLElement>) {
    const isEscape = event.key === 'Escape';
    if (isEscape && isPickingOwner) {
      onHideOwners();
    }
  }

  return (
    <div className='pointer-events-none sticky bottom-4 z-10 flex h-11 justify-center'>
      <AnimatePresence initial={false}>
        {hasSelection && (
          <motion.section
            key='bulk'
            aria-label='Selected accounts'
            onKeyDown={leaveOwnersOnEscape}
            className='surface-raised pointer-events-auto flex h-11 max-w-full items-center gap-2 rounded-full ps-4 pe-1.5'
            {...presence}
          >
            <p
              className={cn(
                'shrink-0 items-baseline gap-1 text-[13px] font-medium',
                countVisibilityOf(isPickingOwner)
              )}
            >
              <MotionNumber value={count} />
              selected
            </p>
            <AnimatedSize axis='width'>
              {isPickingOwner && (
                <div role='group' aria-label='Assign to' className={CHOICES}>
                  <span className='text-muted-foreground hidden pe-1 text-xs @lg:inline'>
                    Assign to
                  </span>
                  {OWNERS.map((owner) => (
                    <Button
                      key={owner.id}
                      type='button'
                      variant='ghost'
                      size='sm'
                      data-bulk-owner={owner.id}
                      aria-label={`Assign to ${owner.name}`}
                      onClick={() => onAssign(owner.id)}
                      className={cn(
                        'gap-1 px-1.5 @lg:gap-1.5',
                        pressedQuietOf(pressed === `owner-${owner.id}`)
                      )}
                    >
                      <Avatar seed={owner.name} className='size-4 @lg:size-5' />
                      {owner.firstName}
                    </Button>
                  ))}
                  <Button
                    type='button'
                    variant='ghost'
                    size='icon-sm'
                    aria-label='Back to the actions'
                    onClick={onHideOwners}
                    className='text-muted-foreground'
                  >
                    <XIcon />
                  </Button>
                </div>
              )}
              {!isPickingOwner && (
                <div className={CHOICES}>
                  <Button
                    type='button'
                    variant='ghost'
                    size='sm'
                    data-bulk-assign
                    onClick={onShowOwners}
                    className={pressedQuietOf(pressed === 'assign')}
                  >
                    Assign owner
                  </Button>
                  <Button
                    type='button'
                    variant='ghost'
                    size='sm'
                    onClick={onExport}
                  >
                    <Swap swapKey={exportWord}>{exportWord}</Swap>
                  </Button>
                  <Button
                    type='button'
                    variant='ghost'
                    size='icon-sm'
                    aria-label='Clear the selection'
                    onClick={onClear}
                    className='text-muted-foreground'
                  >
                    <XIcon />
                  </Button>
                </div>
              )}
            </AnimatedSize>
          </motion.section>
        )}
      </AnimatePresence>
    </div>
  );
}

import {
  PLAN_LABEL,
  PLANS,
  REGION_LABEL,
  REGIONS,
  renewsThisQuarter,
  type Account,
  type PlanId,
  type RegionId,
} from './data';

export const ASK_EXAMPLE = 'enterprise in europe over 100 seats';

export const ASK_FAILED_LINE =
  'Nothing to filter in that. Name a plan, a region, seats over or under a number, or what renews this quarter.';

export type Filter =
  | { kind: 'plan'; plans: PlanId[] }
  | { kind: 'region'; regions: RegionId[] }
  | { kind: 'seatsOver'; count: number }
  | { kind: 'seatsUnder'; count: number }
  | { kind: 'renewal' };

export type FilterKind = Filter['kind'];

const PLAN_PHRASES: Record<PlanId, string[]> = {
  starter: ['starter'],
  team: ['team', 'teams'],
  business: ['business'],
  enterprise: ['enterprise', 'enterprises'],
};

const REGION_PHRASES: Record<RegionId, string[]> = {
  europe: ['europe', 'european', 'eu'],
  'north-america': ['north america', 'north american', 'usa', 'canada'],
  'asia-pacific': ['asia pacific', 'asia', 'asian', 'apac'],
  'latin-america': ['latin america', 'latin american', 'latam'],
};

const RENEWAL_PHRASES = [
  'renew',
  'renews',
  'renewing',
  'renewal',
  'renewals',
  'expires',
  'expiring',
];

const OVER = /\b(?:over|above|more than|bigger than|larger than) (\d+)\b/;

const UNDER = /\b(?:under|below|fewer than|less than|smaller than) (\d+)\b/;

/** Lower case words between single spaces, with a space at both ends so a phrase is matched whole. */
function sentenceOf(text: string) {
  const lowered = text.toLowerCase();
  const spaced = lowered.replace(/[^a-z0-9]+/g, ' ');
  const trimmed = spaced.trim();
  return ` ${trimmed} `;
}

function names(sentence: string, phrases: string[]) {
  return phrases.some((phrase) => sentence.includes(` ${phrase} `));
}

function countAfter(sentence: string, bound: RegExp) {
  const match = bound.exec(sentence);
  if (!match) {
    return null;
  }
  return Number(match[1]);
}

/**
 * Reads a plain question into filters with a handful of word lists: no model is called.
 * It returns nothing when the question names nothing the table can filter on.
 */
export function filtersOfQuestion(text: string): Filter[] | null {
  const sentence = sentenceOf(text);
  const filters: Filter[] = [];
  const plans = PLANS.filter((plan) => names(sentence, PLAN_PHRASES[plan]));
  if (plans.length > 0) {
    filters.push({ kind: 'plan', plans });
  }
  const regions = REGIONS.filter((region) =>
    names(sentence, REGION_PHRASES[region])
  );
  if (regions.length > 0) {
    filters.push({ kind: 'region', regions });
  }
  const over = countAfter(sentence, OVER);
  if (over !== null) {
    filters.push({ kind: 'seatsOver', count: over });
  }
  const under = countAfter(sentence, UNDER);
  if (under !== null) {
    filters.push({ kind: 'seatsUnder', count: under });
  }
  if (names(sentence, RENEWAL_PHRASES)) {
    filters.push({ kind: 'renewal' });
  }
  if (filters.length === 0) {
    return null;
  }
  return filters;
}

/** A new question adds to what is already asked: it replaces a filter of the same kind and keeps the others in place. */
export function mergedFilters(current: Filter[], asked: Filter[]) {
  const kept = current.map((filter) => {
    const replacement = asked.find(
      (candidate) => candidate.kind === filter.kind
    );
    return replacement ?? filter;
  });
  const currentKinds = current.map((filter) => filter.kind);
  const added = asked.filter((filter) => !currentKinds.includes(filter.kind));
  return [...kept, ...added];
}

function orListOf(labels: string[]) {
  return labels.join(' or ');
}

export function filterLabelOf(filter: Filter) {
  switch (filter.kind) {
    case 'plan': {
      const labels = filter.plans.map((plan) => PLAN_LABEL[plan]);
      return `Plan: ${orListOf(labels)}`;
    }
    case 'region': {
      const labels = filter.regions.map((region) => REGION_LABEL[region]);
      return `Region: ${orListOf(labels)}`;
    }
    case 'seatsOver':
      return `Seats over ${filter.count}`;
    case 'seatsUnder':
      return `Seats under ${filter.count}`;
    case 'renewal':
      return 'Renews this quarter';
  }
}

export function matchesFilter(account: Account, filter: Filter) {
  switch (filter.kind) {
    case 'plan':
      return filter.plans.includes(account.plan);
    case 'region':
      return filter.regions.includes(account.region);
    case 'seatsOver':
      return account.seats > filter.count;
    case 'seatsUnder':
      return account.seats < filter.count;
    case 'renewal':
      return renewsThisQuarter(account);
  }
}

import {
  HEALTH_LABEL,
  ownerOf,
  PLAN_LABEL,
  REGION_LABEL,
  type Account,
} from './data';
import { ownerIdOf, type Owners } from './session';

const HEADER = [
  'Account',
  'Plan',
  'Region',
  'Seats',
  'Renewal',
  'Health',
  'Owner',
];

const FORMULA_PREFIXES = ['=', '+', '-', '@'];

/** Spreadsheet apps run a cell that starts with these characters as a formula. */
function neutralizedCellOf(value: string) {
  const startsLikeFormula = FORMULA_PREFIXES.some((prefix) =>
    value.startsWith(prefix)
  );
  if (startsLikeFormula) {
    return `'${value}`;
  }
  return value;
}

function csvCellOf(value: string) {
  const neutralized = neutralizedCellOf(value);
  const escaped = neutralized.replaceAll('"', '""');
  return `"${escaped}"`;
}

function csvLineOf(row: string[]) {
  const cells = row.map(csvCellOf);
  return cells.join(',');
}

/** One line per account, with the owner a person may have assigned since the page loaded. */
export function csvRowsOf(accounts: Account[], owners: Owners) {
  const rows = accounts.map((account) => {
    const ownerId = ownerIdOf(owners, account);
    return [
      account.name,
      PLAN_LABEL[account.plan],
      REGION_LABEL[account.region],
      String(account.seats),
      account.renewal,
      HEALTH_LABEL[account.health],
      ownerOf(ownerId).name,
    ];
  });
  return [HEADER, ...rows];
}

/** Builds the file in the browser and hands it to the download bar: nothing leaves the page. */
export function downloadCsv(fileName: string, rows: string[][]) {
  const lines = rows.map(csvLineOf);
  const text = lines.join('\n');
  const file = new Blob([text], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(file);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  link.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';
import { keyDelayOf, prefixesOf } from '@/registry/ndeko/lib/demonstration';

import {
  ASK_EXAMPLE,
  ASK_FAILED_LINE,
  filtersOfQuestion,
  matchesFilter,
  mergedFilters,
  type Filter,
  type FilterKind,
} from './ask';
import {
  accountOf,
  ACCOUNTS,
  ownerOf,
  PLAN_RANK,
  renewsThisQuarter,
  summaryOf,
  type Account,
  type OwnerId,
} from './data';

export type ViewId = 'all' | 'risk' | 'renewing';

export type View = {
  id: ViewId;
  label: string;
};

export const VIEWS: View[] = [
  { id: 'all', label: 'All' },
  { id: 'risk', label: 'At risk' },
  { id: 'renewing', label: 'Renewing' },
];

export type SortColumn = 'name' | 'plan' | 'seats' | 'renewal';

export type SortDirection = 'asc' | 'desc';

export type Sort = {
  column: SortColumn;
  direction: SortDirection;
};

export const SORT_LABEL: Record<SortColumn, string> = {
  name: 'Account',
  plan: 'Plan',
  seats: 'Seats',
  renewal: 'Renewal',
};

/** A column of figures starts from the largest; names and dates start from the first. */
const FIRST_DIRECTION: Record<SortColumn, SortDirection> = {
  name: 'asc',
  plan: 'desc',
  seats: 'desc',
  renewal: 'asc',
};

const DIRECTION_WORD: Record<SortDirection, string> = {
  asc: 'ascending',
  desc: 'descending',
};

export type BulkMode = 'actions' | 'owners';

export type Owners = Partial<Record<string, OwnerId>>;

export const PAGE_SIZE = 8;

export type AccountsState = {
  question: string;
  hasAskFailed: boolean;
  filters: Filter[];
  view: ViewId;
  sort: Sort;
  page: number;
  selected: string[];
  bulkMode: BulkMode;
  /** The owners a person assigned, by account. The others keep the owner of the data. */
  owners: Owners;
  openSummaries: string[];
  /** A summary is written once: opened again, it is there at once. */
  writtenSummaries: string[];
  /** The summary whose words are arriving. */
  streamingSummary: string | null;
  /** Counts the changes of the rows on screen. Rows only fade in after the first one, never on load. */
  revision: number;
  spoken: string;
};

export type AccountsAction =
  | { type: 'questionTyped'; text: string }
  | { type: 'asked' }
  | { type: 'filterRemoved'; kind: FilterKind }
  | { type: 'filtersCleared' }
  | { type: 'viewPicked'; view: ViewId }
  | { type: 'sorted'; column: SortColumn }
  | { type: 'pageTurned'; page: number }
  | { type: 'rowToggled'; id: string }
  | { type: 'pageToggled' }
  | { type: 'selectionCleared' }
  | { type: 'bulkModeSet'; mode: BulkMode }
  | { type: 'ownerAssigned'; owner: OwnerId }
  | { type: 'exported' }
  | { type: 'summaryToggled'; id: string };

type Step = SessionStep<AccountsState, AccountsAction>;

export const INITIAL: AccountsState = {
  question: '',
  hasAskFailed: false,
  filters: [],
  view: 'all',
  sort: { column: 'name', direction: 'asc' },
  page: 0,
  selected: [],
  bulkMode: 'actions',
  owners: {},
  openSummaries: [],
  writtenSummaries: [],
  streamingSummary: null,
  revision: 0,
  spoken: '',
};

export function ownerIdOf(owners: Owners, account: Account) {
  return owners[account.id] ?? account.owner;
}

function isInView(account: Account, view: ViewId) {
  if (view === 'risk') {
    return account.health === 'risk';
  }
  if (view === 'renewing') {
    return renewsThisQuarter(account);
  }
  return true;
}

/** The accounts the filters keep, whatever the view. The tabs count from them. */
export function matchingOf(filters: Filter[]) {
  return ACCOUNTS.filter((account) =>
    filters.every((filter) => matchesFilter(account, filter))
  );
}

export function viewCountOf(matching: Account[], view: ViewId) {
  const inView = matching.filter((account) => isInView(account, view));
  return inView.length;
}

function orderOf(first: Account, second: Account, column: SortColumn) {
  if (column === 'seats') {
    return first.seats - second.seats;
  }
  if (column === 'plan') {
    return PLAN_RANK[first.plan] - PLAN_RANK[second.plan];
  }
  if (column === 'renewal') {
    return first.renewal.localeCompare(second.renewal);
  }
  return first.name.localeCompare(second.name);
}

/** Two accounts level on the sorted column keep the order of their names, whatever the direction. */
function sortedBy(accounts: Account[], sort: Sort) {
  const sorted = [...accounts];
  sorted.sort((first, second) => {
    const order = orderOf(first, second, sort.column);
    if (order === 0) {
      return first.name.localeCompare(second.name);
    }
    if (sort.direction === 'desc') {
      return -order;
    }
    return order;
  });
  return sorted;
}

export function resultOf(filters: Filter[], view: ViewId, sort: Sort) {
  const matching = matchingOf(filters);
  const inView = matching.filter((account) => isInView(account, view));
  return sortedBy(inView, sort);
}

export function pageCountOf(total: number) {
  const pages = Math.ceil(total / PAGE_SIZE);
  return Math.max(1, pages);
}

export function pageRowsOf(result: Account[], page: number) {
  const start = page * PAGE_SIZE;
  return result.slice(start, start + PAGE_SIZE);
}

export function accountsWordOf(count: number) {
  if (count === 1) {
    return 'account';
  }
  return 'accounts';
}

function countLineOf(count: number) {
  return `${count} ${accountsWordOf(count)}`;
}

function resultOfState(state: AccountsState) {
  return resultOf(state.filters, state.view, state.sort);
}

/** The bar shows its actions again once nothing is selected. */
function bulkModeFor(selected: string[], mode: BulkMode): BulkMode {
  if (selected.length === 0) {
    return 'actions';
  }
  return mode;
}

/**
 * The rows changed: the list starts again at its first page, and a selected account that left the
 * list leaves the selection, so a bulk action never touches a row nobody can see.
 */
function withNewResult(
  state: AccountsState,
  spokenOf: (count: number) => string
): AccountsState {
  const result = resultOfState(state);
  const visibleIds = result.map((account) => account.id);
  const selected = state.selected.filter((id) => visibleIds.includes(id));
  return {
    ...state,
    page: 0,
    selected,
    bulkMode: bulkModeFor(selected, state.bulkMode),
    streamingSummary: null,
    revision: state.revision + 1,
    spoken: spokenOf(result.length),
  };
}

function matchLineOf(count: number) {
  if (count === 1) {
    return '1 account matches';
  }
  return `${count} accounts match`;
}

function asked(state: AccountsState): AccountsState {
  const askedFilters = filtersOfQuestion(state.question);
  if (!askedFilters) {
    return { ...state, hasAskFailed: true, spoken: ASK_FAILED_LINE };
  }
  const filters = mergedFilters(state.filters, askedFilters);
  const next = { ...state, filters, question: '', hasAskFailed: false };
  return withNewResult(next, matchLineOf);
}

function filterRemoved(state: AccountsState, kind: FilterKind): AccountsState {
  const filters = state.filters.filter((filter) => filter.kind !== kind);
  const next = { ...state, filters };
  return withNewResult(
    next,
    (count) => `Filter removed, ${countLineOf(count)}`
  );
}

function filtersCleared(state: AccountsState): AccountsState {
  const next = { ...state, filters: [], hasAskFailed: false };
  return withNewResult(next, (count) => `No filter, ${countLineOf(count)}`);
}

function viewLabelOf(id: ViewId) {
  const view = VIEWS.find((candidate) => candidate.id === id);
  return view?.label ?? '';
}

function viewPicked(state: AccountsState, view: ViewId): AccountsState {
  if (state.view === view) {
    return state;
  }
  const label = viewLabelOf(view);
  const next = { ...state, view };
  return withNewResult(next, (count) => `${label}, ${countLineOf(count)}`);
}

function directionAfter(sort: Sort, column: SortColumn): SortDirection {
  if (sort.column !== column) {
    return FIRST_DIRECTION[column];
  }
  if (sort.direction === 'asc') {
    return 'desc';
  }
  return 'asc';
}

function sorted(state: AccountsState, column: SortColumn): AccountsState {
  const direction = directionAfter(state.sort, column);
  const spoken = `Sorted by ${SORT_LABEL[column]}, ${DIRECTION_WORD[direction]}`;
  return {
    ...state,
    sort: { column, direction },
    page: 0,
    streamingSummary: null,
    revision: state.revision + 1,
    spoken,
  };
}

function pageTurned(state: AccountsState, target: number): AccountsState {
  const result = resultOfState(state);
  const pageCount = pageCountOf(result.length);
  const lastPage = pageCount - 1;
  const atLeastFirst = Math.max(0, target);
  const page = Math.min(lastPage, atLeastFirst);
  if (page === state.page) {
    return state;
  }
  return {
    ...state,
    page,
    streamingSummary: null,
    revision: state.revision + 1,
    spoken: `Page ${page + 1} of ${pageCount}`,
  };
}

function selectedLineOf(count: number) {
  if (count === 0) {
    return 'Nothing selected';
  }
  return `${count} selected`;
}

function withSelection(state: AccountsState, selected: string[]) {
  return {
    ...state,
    selected,
    bulkMode: bulkModeFor(selected, state.bulkMode),
    spoken: selectedLineOf(selected.length),
  };
}

function rowToggled(state: AccountsState, id: string): AccountsState {
  const isSelected = state.selected.includes(id);
  if (isSelected) {
    const selected = state.selected.filter((candidate) => candidate !== id);
    return withSelection(state, selected);
  }
  return withSelection(state, [...state.selected, id]);
}

/** The box of the header selects the rows of the page, or lets go of them when they all are. */
function pageToggled(state: AccountsState): AccountsState {
  const rows = pageRowsOf(resultOfState(state), state.page);
  const pageIds = rows.map((account) => account.id);
  if (pageIds.length === 0) {
    return state;
  }
  const isPageSelected = pageIds.every((id) => state.selected.includes(id));
  if (isPageSelected) {
    const selected = state.selected.filter((id) => !pageIds.includes(id));
    return withSelection(state, selected);
  }
  const missing = pageIds.filter((id) => !state.selected.includes(id));
  return withSelection(state, [...state.selected, ...missing]);
}

function ownerAssigned(state: AccountsState, owner: OwnerId): AccountsState {
  const count = state.selected.length;
  if (count === 0) {
    return state;
  }
  const owners: Owners = { ...state.owners };
  for (const id of state.selected) {
    owners[id] = owner;
  }
  const spoken = `${countLineOf(count)} assigned to ${ownerOf(owner).name}`;
  return { ...state, owners, selected: [], bulkMode: 'actions', spoken };
}

function summaryToggled(state: AccountsState, id: string): AccountsState {
  const isOpen = state.openSummaries.includes(id);
  if (isOpen) {
    const openSummaries = state.openSummaries.filter(
      (candidate) => candidate !== id
    );
    return { ...state, openSummaries, streamingSummary: null, spoken: '' };
  }
  const account = accountOf(id);
  const openSummaries = [...state.openSummaries, id];
  const spoken = `${account.name}: ${summaryOf(account)}`;
  const isWritten = state.writtenSummaries.includes(id);
  if (isWritten) {
    return { ...state, openSummaries, streamingSummary: null, spoken };
  }
  return {
    ...state,
    openSummaries,
    writtenSummaries: [...state.writtenSummaries, id],
    streamingSummary: id,
    spoken,
  };
}

export function reducer(
  state: AccountsState,
  action: AccountsAction
): AccountsState {
  switch (action.type) {
    case 'questionTyped':
      return { ...state, question: action.text, hasAskFailed: false };
    case 'asked':
      return asked(state);
    case 'filterRemoved':
      return filterRemoved(state, action.kind);
    case 'filtersCleared':
      return filtersCleared(state);
    case 'viewPicked':
      return viewPicked(state, action.view);
    case 'sorted':
      return sorted(state, action.column);
    case 'pageTurned':
      return pageTurned(state, action.page);
    case 'rowToggled':
      return rowToggled(state, action.id);
    case 'pageToggled':
      return pageToggled(state);
    case 'selectionCleared':
      return withSelection(state, []);
    case 'bulkModeSet':
      return { ...state, bulkMode: bulkModeFor(state.selected, action.mode) };
    case 'ownerAssigned':
      return ownerAssigned(state, action.owner);
    case 'exported': {
      const spoken = `${countLineOf(state.selected.length)} exported`;
      return { ...state, spoken };
    }
    case 'summaryToggled':
      return summaryToggled(state, action.id);
  }
}

const KEY_MS = 45;

function typingSteps(text: string, startAfter: number): Step[] {
  const prefixes = prefixesOf(text);
  return prefixes.map((typed, index) => ({
    after: keyDelayOf(index, startAfter, KEY_MS),
    by: 'demo',
    action: { type: 'questionTyped', text: typed },
  }));
}

